UPDATE t_payment_order
SET status = 'SUCCESS', success_time = #{successTime}
WHERE payment_order_no = #{paymentOrderNo} AND status = #{fromStatus}

UPDATE t_payment_order
SET status = 'FAILED'
WHERE payment_order_no = #{paymentOrderNo}
  AND status IN

    #{s}

UPDATE t_payment_order
SET refunded_amount = refunded_amount + #{amount}
WHERE payment_order_no = #{paymentOrderNo}
  AND refunded_amount + #{amount} <= amount

UPDATE t_payment_order
SET status = 'CLOSED', close_type = #{closeType}, close_time = #{closeTime}
WHERE payment_order_no IN

    #{no}

  AND status IN

    #{s}
